CREATE OR REPLACE FUNCTION public.attack_player(target_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare a public.profiles;d public.profiles;a_item_att int:=0;d_item_def int:=0;a_pet_att int:=0;d_pet_def int:=0;a_gang_att int:=0;d_gang_def int:=0;d_defense_bonus int:=0;a_power int;d_power int;winner uuid;loot numeric(12,2):=0;result text; begin if target_id=auth.uid() then raise exception 'Du kannst dich nicht selbst vermöbeln';end if; select * into a from public.profiles where id=auth.uid() for update; select * into d from public.profiles where id=target_id for update; if a.id is null or a.is_banned then raise exception 'Zugriff gesperrt';end if; if d.id is null or d.is_banned then raise exception 'Gegner verschwunden';end if; if a.collection_ends_at is not null then raise exception 'Dein Einkaufswagen ist unterwegs oder wartet aufs Ausladen';end if; if a.energy<15 then raise exception 'Nicht genug Energie für eine Prügelei';end if; if d.protection_until is not null and d.protection_until>now() then raise exception 'Dieser Spieler steht noch unter Schutz';end if; if exists(select 1 from public.fights where attacker_id=auth.uid() and defender_id=target_id and created_at>now()-interval '10 minutes') then raise exception 'Diesen Spieler hast du kürzlich schon besucht';end if; select coalesce(sum(s.attack),0) into a_item_att from public.inventory i join public.shop_items s on s.id=i.item_id where i.user_id=auth.uid() and i.equipped; select coalesce(sum(s.defense),0) into d_item_def from public.inventory i join public.shop_items s on s.id=i.item_id where i.user_id=target_id and i.equipped; select coalesce(sum(pc.attack*up.attack_level),0) into a_pet_att from public.user_pets up join public.pet_catalog pc on pc.id=up.pet_id where up.user_id=auth.uid() and up.active; select coalesce(sum(pc.defense*up.defense_level),0) into d_pet_def from public.user_pets up join public.pet_catalog pc on pc.id=up.pet_id where up.user_id=target_id and up.active; select coalesce(g.attack_level*2,0) into a_gang_att from public.gang_members gm join public.gangs g on g.id=gm.gang_id where gm.user_id=auth.uid(); select coalesce(g.defense_level*2,0) into d_gang_def from public.gang_members gm join public.gangs g on g.id=gm.gang_id where gm.user_id=target_id; select coalesce(sum(amount),0) into d_defense_bonus from public.user_active_defenses where user_id=target_id and (expires_at is null or expires_at>now()); a_power:=a.attack_skill*3+a.streetwise+a_item_att+a_pet_att+a_gang_att+floor(random()*8)::int; d_power:=d.defense_skill*3+d.shelter_level*2+d_item_def+d_pet_def+d_gang_def+d_defense_bonus+floor(random()*8)::int; if a_power>d_power then winner:=a.id;loot:=least(round(d.money*0.10,2),greatest(0,a.cash_capacity-a.money));result:='win'; update public.profiles set money=money+loot,energy=energy-15,xp=xp+15,wins=wins+1 where id=a.id returning * into a; update public.profiles set money=greatest(0,money-loot),losses=losses+1,protection_until=now()+interval '5 minutes' where id=d.id; else winner:=d.id;result:='loss'; update public.profiles set energy=energy-15,losses=losses+1,protection_until=now()+interval '2 minutes' where id=a.id returning * into a; update public.profiles set wins=wins+1 where id=d.id; end if; delete from public.user_active_defenses where user_id=target_id and consume_on_attack=true and (expires_at is null or expires_at>now()); insert into public.fights(attacker_id,defender_id,winner_id,attacker_power,defender_power,loot) values(a.id,d.id,winner,a_power,d_power,loot); return jsonb_build_object('result',result,'attacker_power',a_power,'defender_power',d_power,'loot',loot,'opponent',d.username,'profile',to_jsonb(a),'pet_bonus',a_pet_att,'gang_bonus',a_gang_att,'defender_defense_bonus',d_defense_bonus); end $function$;
